    if n == 0:
        return 0
    dp = [0] * n
    dp[0] = values[0]
    for i in range(1, n):
        best = None
        if i >= 1:
            best = dp[i - 1]
        if i >= 2:
            best = dp[i - 2] if best is None else max(best, dp[i - 2])
        dp[i] = values[i] + best
    return dp[-1]
```

```python
def max_circular_subarray_sum(nums):
