    if n == 0:
        return 0
    total = sum(nums)
    best = cur = nums[0]
    for i in range(1, n):
        x = nums[i]
        cur = max(x, cur + x)
        best = max(best, cur)
    if best < 0:
        return best
    return max(best, total - min(cur = nums[0], cur = max(cur + x, x) for x in nums[1:]))
```

